#!/usr/bin/env bash
# bootstrap-machine.sh - recreate the machine-local half of the Claude setup.
#
# ~/.claude is version controlled (claude-code-config), but .gitignore
# deliberately excludes plugins/, .claude.json and settings.json. So git
# carries CLAUDE.md, rules, hooks, agents and skills - but NOT plugins,
# MCP servers, or the settings.json that REGISTERS the hooks.
#
# Run this on a new machine AFTER cloning claude-code-config into ~/.claude.
#
# GENERATED by scripts/gen-bootstrap.py - re-run it after adding plugins or MCPs.
set -uo pipefail

echo "== marketplaces =="
claude plugin marketplace add "accesslint" || true
claude plugin marketplace add "last30days-skill" || true
claude plugin marketplace add "superpowers-marketplace" || true
claude plugin marketplace add "ui-ux-pro-max-skill" || true

echo "== plugins (17) =="
claude plugin install "accesslint@accesslint" || true
claude plugin install "code-modernization@claude-plugins-official" || true
claude plugin install "code-review@claude-plugins-official" || true
claude plugin install "code-simplifier@claude-plugins-official" || true
claude plugin install "commit-commands@claude-plugins-official" || true
claude plugin install "feature-dev@claude-plugins-official" || true
claude plugin install "frontend-design@claude-plugins-official" || true
claude plugin install "hookify@claude-plugins-official" || true
claude plugin install "last30days@last30days-skill" || true
claude plugin install "pr-review-toolkit@claude-plugins-official" || true
claude plugin install "pyright-lsp@claude-plugins-official" || true
claude plugin install "ralph-loop@claude-plugins-official" || true
claude plugin install "security-guidance@claude-plugins-official" || true
claude plugin install "skill-creator@claude-plugins-official" || true
claude plugin install "superpowers@superpowers-marketplace" || true
claude plugin install "typescript-lsp@claude-plugins-official" || true
claude plugin install "ui-ux-pro-max@ui-ux-pro-max-skill" || true

echo "== MCP servers (12) =="
# Secrets are NOT stored here. Export the named vars first, or let the
# server prompt for OAuth on first use.

claude mcp add --env BING_WEBMASTER_API_KEY="${BING_WEBMASTER_API_KEY:?set BING_WEBMASTER_API_KEY}" "bing-webmaster" -- "cmd" "/c" "npx" "-y" "@isiahw1/mcp-server-bing-webmaster@latest" || true
claude mcp add --transport http "cloudflare" "https://mcp.cloudflare.com/mcp" || true
claude mcp add "context7" -- "cmd" "/c" "npx" "-y" "@upstash/context7-mcp" || true
claude mcp add "google-news-trends" -- "uvx" "--with" "fastmcp>=2.9.2,<3" "google-news-trends-mcp" || true
claude mcp add --env GSC_OAUTH_CLIENT_SECRETS_FILE="${GSC_OAUTH_CLIENT_SECRETS_FILE:?set GSC_OAUTH_CLIENT_SECRETS_FILE}" --env GSC_DATA_STATE="${GSC_DATA_STATE:?set GSC_DATA_STATE}" "gsc" -- "C:\Users\Kenny\.mcp-gsc\.venv\Scripts\python.exe" "C:\Users\Kenny\.mcp-gsc\gsc_server.py" || true
claude mcp add --transport http "meta-ads" "https://mcp.pipeboard.co/meta-ads-mcp" || true
claude mcp add "playwright" -- "cmd" "/c" "npx" "-y" "@playwright/mcp@latest" || true
claude mcp add --transport http "sentry" "https://mcp.sentry.dev/mcp" || true
claude mcp add "sequential-thinking" -- "cmd" "/c" "npx" "-y" "@modelcontextprotocol/server-sequential-thinking" || true
claude mcp add --transport http "trello" "https://mcp.trello.com/v1" || true
claude mcp add "ux-best-practices" -- "cmd" "/c" "npx" "-y" "@elsahafy/ux-mcp-server" || true
claude mcp add --transport http "vercel" "https://mcp.vercel.com" || true

echo "== required env vars =="
[ -n "${BING_WEBMASTER_API_KEY:-}" ] || echo "  MISSING: BING_WEBMASTER_API_KEY"
[ -n "${GSC_OAUTH_CLIENT_SECRETS_FILE:-}" ] || echo "  MISSING: GSC_OAUTH_CLIENT_SECRETS_FILE"

echo "== manual steps git cannot carry =="
cat <<'EOF'
  1. settings.json is gitignored - it REGISTERS the hooks. Without it the
     hook scripts exist but never fire. Copy it from the other machine.
  2. Language servers: npm install -g typescript-language-server typescript pyright
  3. Memory: clone claude-memory, then re-create the junctions
     (~/.claude/projects/<slug>/memory -> ~/claude-memory/projects/<name>).
  4. Secrets/.env files are not in git - copy them across separately.
EOF

